// Captura
const assunto = $json.subject || "Sem assunto";
const corpoOriginal = $json.text || $json.html || "Sem conteúdo";
const remetente = $json.from || "Desconhecido";
const dataRecebimento = $json.date || new Date().toISOString();

let corpo = corpoOriginal
  .replace(/(<[^>]+>)/g, "")
  .replace(/\r\n/g, "\n")
  .replace(/\n{3,}/g, "\n\n")
  .trim();

let categoria = "geral";
if (corpo.toLowerCase().includes("erro") || corpo.includes("alerta")) categoria = "alerta";
if (corpo.toLowerCase().includes("fatura") || corpo.includes("pagamento")) categoria = "financeiro";
if (corpo.toLowerCase().includes("vaga") || corpo.toLowerCase().includes("currículo")) categoria = "rh";

const palavrasChave = [];
const padroes = ["erro", "falha", "pagamento", "fatura", "suporte", "urgente", "alerta", "pedido"];
for (const palavra of padroes) {
  if (corpo.toLowerCase().includes(palavra)) palavrasChave.push(palavra);
}

const textoFormatado = `Assunto: ${assunto}\nDe: ${remetente}\nData: ${dataRecebimento}\n\nCategoria: ${categoria}\nPalavras-chave detectadas: ${palavrasChave.join(", ") || "Nenhuma"}\n\nCorpo formatado:\n${corpo}\n`;

return {
  json: { assunto, corpo, remetente, dataRecebimento, categoria, palavrasChave, textoFormatado }
};

List<String> emails = Arrays.asList(
    "example1@gmail.com",
    "example2@gmail.com",
    "example3@gmail.com"
);

List<Map<String, Object>> out = new ArrayList<>();
for (String e : emails) {
    Map<String, Object> item = new HashMap<>();
    item.put("email", e);
    item.put("assunto", "Aviso Automático");
    item.put("mensagem", "Mensagem enviada automaticamente pelo workflow.");
    out.add(item);
}
return out;
